using Microsoft.EntityFrameworkCore;
namespace Society.Api;
public static class CommunityMetrics {
 public static async Task<IResult> Read(Guid tenant,Guid? workspace,DateTimeOffset? from,DateTimeOffset? to,AppDb db,Access a){
 await a.Member(tenant);var all=await a.Can(tenant,"activities.analytics");var unitsQuery=a.InWorkspace(a.Visible(tenant,"activities.analytics"),tenant,workspace);if(!all&&!await unitsQuery.AnyAsync())throw new AccessDeniedException();var start=from??DateTimeOffset.UtcNow.AddDays(-90);var end=to??DateTimeOffset.UtcNow;if(end<=start||end-start>TimeSpan.FromDays(366))throw new DomainException("Select up to one year");
 var visible=await (from u in unitsQuery join l in db.Levels on u.LevelId equals l.Id select new{u.Id,u.Name,u.ParentId,l.Kind}).ToListAsync();var ids=visible.Select(u=>u.Id).ToArray();var full=all&&workspace==null;
 var posts=db.Set<ActivityPost>().Where(p=>p.TenantId==tenant&&p.Status=="Published"&&p.PublishedAt>=start&&p.PublishedAt<end);if(!full)posts=posts.Where(p=>p.UnitId!=null&&ids.Contains(p.UnitId.Value));
 var events=db.Set<CommunityEvent>().Where(e=>e.TenantId==tenant&&e.Status=="Published"&&e.StartsAt>=start&&e.StartsAt<end);if(!full)events=events.Where(e=>e.UnitId!=null&&ids.Contains(e.UnitId.Value));
 var eventIds=events.Select(e=>e.Id);var attendance=db.Set<EventAttendance>().Where(at=>at.TenantId==tenant&&eventIds.Contains(at.EventId)&&!at.Voided);var regs=db.Set<EventRegistration>().Where(r=>r.TenantId==tenant&&eventIds.Contains(r.EventId));
 var postGroups=await posts.Where(p=>p.UnitId!=null).GroupBy(p=>p.UnitId!.Value).Select(g=>new{id=g.Key,count=g.Count()}).ToDictionaryAsync(x=>x.id,x=>x.count);
 var eventGroups=await events.Where(e=>e.UnitId!=null).GroupBy(e=>e.UnitId!.Value).Select(g=>new{id=g.Key,count=g.Count()}).ToDictionaryAsync(x=>x.id,x=>x.count);
 var attendanceGroups=await (from at in attendance join e in events on at.EventId equals e.Id where e.UnitId!=null group at by e.UnitId!.Value into g select new{id=g.Key,count=g.Count()}).ToDictionaryAsync(x=>x.id,x=>x.count);
 var chapterRows=visible.Where(u=>u.Kind=="Chapter").OrderBy(u=>u.Name).Select(u=>new{u.Id,u.Name,posts=postGroups.GetValueOrDefault(u.Id),events=eventGroups.GetValueOrDefault(u.Id),attendance=attendanceGroups.GetValueOrDefault(u.Id)}).ToList();
 var units=visible.ToDictionary(u=>u.Id);var regional=new Dictionary<Guid,(string name,int posts,int events,int attendance)>();foreach(var u in visible.Where(u=>u.Kind=="Chapter")){var cursor=u.ParentId;var visited=new HashSet<Guid>();while(cursor!=null&&visited.Add(cursor.Value)&&units.TryGetValue(cursor.Value,out var parent)){if(parent.Kind=="Region"){var prior=regional.GetValueOrDefault(parent.Id,(parent.Name,0,0,0));regional[parent.Id]=(parent.Name,prior.Item2+postGroups.GetValueOrDefault(u.Id),prior.Item3+eventGroups.GetValueOrDefault(u.Id),prior.Item4+attendanceGroups.GetValueOrDefault(u.Id));break;}cursor=parent.ParentId;}}
 var upcoming=db.Set<CommunityEvent>().Where(e=>e.TenantId==tenant&&e.Status=="Published"&&e.StartsAt>DateTimeOffset.UtcNow&&e.StartsAt<=DateTimeOffset.UtcNow.AddDays(90));if(!full)upcoming=upcoming.Where(e=>e.UnitId!=null&&ids.Contains(e.UnitId.Value));
 return Results.Ok(new{from=start,to=end,posts=await posts.CountAsync(),contributors=await posts.Select(p=>p.AuthorId).Distinct().CountAsync(),chaptersReporting=chapterRows.Count(c=>c.posts>0),events=await events.CountAsync(),completed=await events.CountAsync(e=>e.EndsAt<DateTimeOffset.UtcNow),upcoming=await upcoming.CountAsync(),registrations=await regs.CountAsync(),actualAttendance=await attendance.CountAsync(),participatingPeople=await regs.Where(r=>attendance.Any(at=>at.RegistrationId==r.Id)).Select(r=>r.UserId).Distinct().CountAsync(),reactions=await db.Set<ActivityReaction>().CountAsync(r=>r.TenantId==tenant&&posts.Any(p=>p.Id==r.PostId)),comments=await db.Set<ActivityComment>().CountAsync(c=>c.TenantId==tenant&&!c.Hidden&&posts.Any(p=>p.Id==c.PostId)),chapterTotal=chapterRows.Count,byChapter=chapterRows.Take(100),byRegion=regional.Select(pair=>new{id=pair.Key,name=pair.Value.name,posts=pair.Value.posts,events=pair.Value.events,attendance=pair.Value.attendance}),byCategory=await (from p in posts join c in db.Set<ActivityCategory>() on p.CategoryId equals c.Id group p by new{c.Id,c.Name} into g select new{id=g.Key.Id,name=g.Key.Name,count=g.Count()}).ToListAsync(),trend=await posts.GroupBy(p=>p.PublishedAt!.Value.Date).Select(g=>new{date=g.Key,count=g.Count()}).OrderBy(g=>g.date).ToListAsync()});
 }
}
